    /** Change a claim's status; the four-eyes and proof rules of a settle are judged on this claim
     *  only when asked (a part-settle judges them on the claim it split off). */
    private Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to, String reason,
            boolean judgeSettle) {
        return changeStatus(sheetId, user, claimId, to, reason, judgeSettle, null);
    }

    /** Change a claim's status; a settle fixes the due as of a day when one is given (null: now). */
    private Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to, String reason,
            boolean judgeSettle, LocalDate on) {
        Claim claim = lock(sheetId, claimId);
        BigDecimal dueThen = on == null ? null : dueAsOf(sheetId, claim, on);
        refuseClosed(sheetId, claim.getDueBy());
        String voidReason = to == ClaimStatus.VOID ? voidReasons.required(sheetId, reason) : null;
        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
            return voidSettled(sheetId, user, claim, voidReason);
        }
        if (!claim.getStatus().canBecome(to) || to == ClaimStatus.PENDING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + to);
        }
        String action = switch (to) {
            case OPEN -> "open";
            case SETTLED -> "settle";
            default -> "void";
        };
        if (!roles.may(sheetId, user, action)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim");
        }
        if (to == ClaimStatus.OPEN) {
            refuseFlagged(sheetId, user, claim);
            refuseUnnoted(sheetId, claim);
            refuseOverCap(sheetId, claim);
        }
        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
        }
        if (to == ClaimStatus.SETTLED && judgeSettle) {
            refuseSameHands(user, claim);
            refuseUnproved(sheetId, claim);
        }
        ClaimStatus becomes = to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, claim)
                ? ClaimStatus.PENDING
                : to == ClaimStatus.OPEN && overReviewThreshold(sheetId, claim) ? ClaimStatus.REVIEW : to;
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            if (becomes == ClaimStatus.SETTLED) {
                // Settling fixes the due at what it is now, while the claim is still open (the figure a
                // statement bound it to, if any, and its late charge); later changes to rates, the
                // late percent and the sheet's today do not alter it.
                claim.setSettledDue(dueThen != null ? dueThen : dues.figure(sheetId, person, claim));
                numberOnSettle(sheetId, claim);
            }
            // A void claim keeps the number it had (never reused).
            claim.setStatus(becomes);
            if (becomes == ClaimStatus.VOID) {
                claim.setVoidReason(voidReason);
            }
            if (becomes == ClaimStatus.OPEN || becomes == ClaimStatus.REVIEW) {
                claim.setOpenedBy(user);
            }
            logStatus(sheetId, user, person, claim);
            Claim saved = claims.saveAndFlush(claim);
            String event = switch (becomes) {
                case OPEN -> "CLAIM_OPENED";
                case REVIEW -> "CLAIM_REVIEW";
                case PENDING -> "CLAIM_PENDING";
                case SETTLED -> "CLAIM_SETTLED";
                case VOID -> "CLAIM_VOIDED";
                case DRAFT, DELETED -> throw new IllegalStateException("a claim is deleted or restored apart");
            };
            String line = record(event, sheetId, user, person, saved);
            if (becomes == ClaimStatus.SETTLED) {
                line += " due=" + dueText(saved.getSettledDue());
                if (on != null) {
                    line += " on=" + on;
                }
            }
            line += reasonText(voidReason);
            audit.recordOnCommit(line);
            if (becomes == ClaimStatus.SETTLED) {
                watches.notifyWatchers(sheetId, user, person, saved.getNumber());
            }
            return saved;
        });
    }

    /** A claim's due as it stood at the end of a day on or before the sheet's today, worked out as
     *  the sheet as of that day works it out. Refused (400) when the day is after the sheet's today,
     *  or when the claim or its person was not on the sheet yet then. */
    private BigDecimal dueAsOf(String sheetId, Claim claim, LocalDate on) {
        if (on.isAfter(sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A claim cannot be settled as of a day after the sheet's today");
        }
        History.SheetAsOf then = history.asOf(sheetId, on);
        Claim claimThen = then.claims().stream().filter(c -> claim.getId().equals(c.getId())).findFirst()
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
                        "The claim was not on the sheet yet on that day"));
        Person personThen = then.person(claimThen.getPersonId())
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
                        "The claim's person was not on the sheet yet on that day"));
        return dues.figure(then.basis(), personThen, claimThen);
    }

    /** Review a claim in review: it becomes open (still with no number), and keeps who opened it.
     *  Refused unless the claim is in review (409), the user is a steward (403), its period is open,
     *  and its person is under its period's cap of open claims. */
    @Transactional
    public Claim review(String sheetId, String user, long claimId) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.REVIEW) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a claim in REVIEW can be reviewed");
        }
        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can review a claim");
        }
        refuseOverCap(sheetId, claim);
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            audit.recordOnCommit(record("CLAIM_REVIEWED", sheetId, user, person, claim));
            claim.setStatus(ClaimStatus.OPEN);
            logStatus(sheetId, user, person, claim);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, saved));
            return saved;
        });
    }

    /** Delete a draft claim: it counts nowhere, and cannot be edited, opened or voided. Refused when
     *  the claim is not a draft, or its period is closed. */
    @Transactional
    public Claim delete(String sheetId, String user, long claimId) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDueBy());
        if (!claim.getStatus().canBecome(ClaimStatus.DELETED) || claim.editLockedFor(user)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be deleted, nor one another user is editing");
        }
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            claim.setStatus(ClaimStatus.DELETED);
            claim.setEditLockedBy(null);

    /** Whether a claim on a sheet other than the one given (null: none) has the reference, comparing
     *  without regard to case. */
    @Query("select count(c) > 0 from Claim c where c.sheetId = :sheetId and upper(c.ref) = upper(:ref)"
            + " and (:exceptId is null or c.id <> :exceptId)")
    boolean refUsed(String sheetId, String ref, Long exceptId);

    /** How many of a person's claims on a sheet are open or pending and due by a day from one date
     *  to another, inclusive. */
    @Query("select count(c) from Claim c where c.sheetId = :sheetId and c.personId = :personId"
            + " and c.status in (net.officefloor.hq.app.claim.ClaimStatus.OPEN, net.officefloor.hq.app.claim.ClaimStatus.PENDING)"
            + " and c.dueBy >= :from and c.dueBy <= :to")
    long countOpenDueBetween(String sheetId, Long personId, LocalDate from, LocalDate to);

    /** The next place in the order claims are added and forward-only rates saved (see Claim#getAdded). */
    @Query(value = "select next value for claim_added_seq", nativeQuery = true)
    long nextAdded();

    /** The next place a claim is listed at, after every claim listed so far. */
    @Query(value = "select next value for claim_listed_seq", nativeQuery = true)
    long nextListed();
            case VOID -> this == DRAFT || this == REVIEW || isOpen();
            case DELETED -> this == DRAFT;
            case DRAFT, REVIEW -> false;
        };
    }

    /** Whether a claim at this status is open: open, or pending approval of its settle. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

        this.claims = claims;
        this.transactions = new TransactionTemplate(transactionManager);
        this.audit = audit;
        this.sheets = sheets;
        this.repository = repository;
        this.people = people;
    }

    /** Open each of the claims that can be opened, numbering them in list order (people in the
     *  order they were added, newest claim first within a person); each that cannot is refused and
     *  left as it is, and so is an id that names no claim on the sheet. */
    public Outcome open(String sheetId, String user, Set<Long> claimIds) {
        return change(sheetId, user, claimIds, ClaimStatus.OPEN);
    }

    /** Settle all the claims or none: when any of them cannot be settled by the user (any refusal
     *  settling one would give; one a clerk's limit leaves pending is not refused), or an id names no
     *  claim on the sheet, none is settled, each counts as refused and nothing is written. Otherwise
     *  each is settled in list order, exactly as settling one, and they are the sheet's next settle
     *  batch, recorded after their own lines with the frozen dues of those settled added up. */
    public Outcome settle(String sheetId, String user, Set<Long> claimIds) {
        if (sheets.archived(sheetId) || claimIds.isEmpty()) {
            return new Outcome(0, claimIds.size());
        }
        Boolean done = transactions.execute(status -> {
            List<Claim> listed = inListOrder(sheetId, claimIds);
            if (listed.size() != claimIds.size()) {
                status.setRollbackOnly();
                return false;
            }
            List<Long> settled = new ArrayList<>();
            BigDecimal total = BigDecimal.ZERO;
            for (Claim claim : listed) {
                Claim saved;
                try {
                    saved = claims.changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED);
                } catch (ResponseStatusException refused) {
                    // one refused: none is settled, and nothing is written
                    status.setRollbackOnly();
                    return false;
                }
                settled.add(saved.getId());
                if (saved.getStatus() == ClaimStatus.SETTLED && saved.getSettledDue() != null) {
                    total = total.add(saved.getSettledDue());
                }
            }
            // the claims it settled are a batch, numbered next on the sheet
            int batch = claims.markSettleBatch(sheetId, settled);
            audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
                    + " count=" + settled.size() + " total=" + total.setScale(2, RoundingMode.HALF_UP).toPlainString());
            return true;
        });
        return Boolean.TRUE.equals(done) ? new Outcome(claimIds.size(), 0) : new Outcome(0, claimIds.size());
    }

    /** Move each of the claims that can be moved to the person, in list order, exactly as moving
     *  one; each that cannot is refused and left as it is, and so is an id that names no claim on the
     *  sheet. */
    public Outcome reassign(String sheetId, String user, Set<Long> claimIds, long toPersonId) {
        if (sheets.archived(sheetId)) {
            return new Outcome(0, claimIds.size());
        }
        int done = 0;
        for (Claim claim : inListOrder(sheetId, claimIds)) {
            try {
                claims.reassign(sheetId, user, claim.getId(), toPersonId, true);
                done++;
            } catch (ResponseStatusException refused) {
                // left as it is
            }
        }
        return new Outcome(done, claimIds.size() - done);
    }

    /** Re-date each of the claims that can be re-dated, in list order, exactly as re-dating one;
     *  each that cannot is refused and left as it is, and so is an id that names no claim on the
     *  sheet. */
    public Outcome redate(String sheetId, String user, Set<Long> claimIds, LocalDate date) {
        if (sheets.archived(sheetId)) {
            return new Outcome(0, claimIds.size());
        }
        int done = 0;
        for (Claim claim : inListOrder(sheetId, claimIds)) {
            try {
                claims.redate(sheetId, user, claim.getId(), date);
                done++;
            } catch (ResponseStatusException refused) {
                // left as it is
            }
        }
        return new Outcome(done, claimIds.size() - done);
    }

    /** Void each of the claims that can be voided, in list order, exactly as voiding one (with the
     *  reason, which the sheet's void reasons may require); each that cannot is refused and left as
     *  it is, and so is an id that names no claim on the sheet. */
    public Outcome voidAll(String sheetId, String user, Set<Long> claimIds, String reason) {
        if (sheets.archived(sheetId)) {
            return new Outcome(0, claimIds.size());
        }
        int done = 0;
        for (Claim claim : inListOrder(sheetId, claimIds)) {
            try {
                claims.voidClaim(sheetId, user, claim.getId(), reason);
                done++;
            } catch (ResponseStatusException refused) {
                // left as it is
            }
        }
        return new Outcome(done, claimIds.size() - done);
    }

    private Outcome change(String sheetId, String user, Set<Long> claimIds, ClaimStatus to) {
        if (sheets.archived(sheetId)) {
            return new Outcome(0, claimIds.size());
        }
        int done = 0;
        for (Claim claim : inListOrder(sheetId, claimIds)) {
            try {
                claims.changeStatus(sheetId, user, claim.getId(), to);
                done++;
            } catch (ResponseStatusException refused) {
                // left as it is
            }
        }
        return new Outcome(done, claimIds.size() - done);
    }

    /** The claims of the ids on the sheet in list order: people in the order they were added, newest
     *  claim first within a person. */
    private List<Claim> inListOrder(String sheetId, Set<Long> claimIds) {
        Map<Long, Integer> rank = new HashMap<>();
        List<Person> listed = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
        for (int i = 0; i < listed.size(); i++) {
            rank.put(listed.get(i).getId(), i);
        }
        return repository.findBySheetIdOrderByListedDesc(sheetId).stream()
                .filter(c -> claimIds.contains(c.getId()))
                .sorted(Comparator.comparingInt((Claim c) -> rank.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
                .toList();
    }
}
    public int paste(String sheetId, String user, String text) {
        List<Claim> before = claims.list(sheetId);
        LocalDate entryDay = sheets.entryDay(sheetId);
        List<Line> lines = new ArrayList<>();
        List<Integer> numbers = new ArrayList<>();
        List<Claim> drafts = new ArrayList<>();
        Set<Long> taken = new HashSet<>();
        Set<String> refs = new HashSet<>();
        int n = 0;
        for (String raw : text.split("\\R")) {
            n++;
            if (!raw.isBlank()) {
                Line line = parse(sheetId, n, raw);
                if (line.ref() != null) {
                    if (!refs.add(line.ref().toUpperCase(Locale.ROOT))) {
                        throw refused(n, "the reference \"" + line.ref() + "\" is repeated in the paste");
                    }
                    try {
