    private Outcome change(String sheetId, String user, Set<Long> claimIds, ClaimStatus to) {
        if (sheets.archived(sheetId)) {
            return new Outcome(0, claimIds.size());
        }
        int done = 0;
        for (Claim claim : inListOrder(sheetId, claimIds)) {
            try {
